        {'questionId':'SEM-Q-021','title':'Compound Attack effects after an intermediate Character death','decisionClass':'source-ambiguity-owner-decision-after-source-search','blocksRuleIds':ATTACK_QUESTION_BLOCKS['SEM-Q-021'],'plannedRuleIds':[],'defaultProhibited':True,'sourceEvidenceRefs':['docs/rules/semantics/attack-source-index.json','docs/rules/open-questions.md:SEM-Q-021'],'alternatives':[{'alternativeId':'SEM-Q-021-A','description':'Stop later Character-bound operations in the selected panel when an earlier Health/Wound operation kills that Character.','support':'a dead Character no longer participates, but no Attack-card continuation sentence states this'},{'alternativeId':'SEM-Q-021-B','description':'Complete every remaining printed operation in the selected panel even after death, including later Contamination/Wound instructions.','support':'standard Attacks say resolve the associated effect before discarding; no explicit stop-on-death rule'},{'alternativeId':'SEM-Q-021-C','description':'Treat coordinated Wound/Contamination outcomes as simultaneous before applying death.','support':'some faces use “and,” but no simultaneous-resolution procedure is supplied'}]},
        {'questionId':'SEM-Q-022','title':'Blood Sense Movement check and relocation after death/interruption','decisionClass':'source-ambiguity-owner-decision-after-source-search','blocksRuleIds':ATTACK_QUESTION_BLOCKS['SEM-Q-022'],'plannedRuleIds':[],'defaultProhibited':True,'sourceEvidenceRefs':['docs/rules/semantics/attack-source-index.json','docs/rules/open-questions.md:SEM-Q-022'],'alternatives':[{'alternativeId':'SEM-Q-022-A','description':'Evaluate “If you are Moving” when Blood Sense is resolved and relocate the attacker to the already selected Movement destination even if the target dies before arriving.','support':'literal future destination wording; death consequence is not addressed'},{'alternativeId':'SEM-Q-022-B','description':'Relocate only if the target remains alive and completes Movement to the selected destination.','support':'“where your Movement ends” may require an actually completed Movement'},{'alternativeId':'SEM-Q-022-C','description':'Use another destination or cancellation rule when death/interruption ends Movement early.','support':'no checked source names one'}]},
