        {'questionId':'SEM-Q-038','title':'Multiple Serious Wound draw, placement, and shortfall order','decisionClass':'official-clarification-preferred','blocksRuleIds':SERIOUS_WOUND_QUESTION_BLOCKS['SEM-Q-038'],'plannedRuleIds':[],'defaultProhibited':True,'sourceEvidenceRefs':['docs/rulebooks/rulebook_text.txt:lines 3538–3548, 3790–3796','docs/rules/open-questions.md:SEM-Q-023','docs/rules/semantics/serious-wound-source-index.json'],'alternatives':[{'alternativeId':'SEM-Q-038-A','description':'Resolve each requested Wound completely in source order—draw, place, displace, activate—before the next.','support':'ordinary singular gain procedure can be repeated, but grouped effects do not always state order'},{'alternativeId':'SEM-Q-038-B','description':'Draw all available Wounds first, then assign/place/activate them by another physical order.','support':'some effects describe several Wounds as one grouped result'},{'alternativeId':'SEM-Q-038-C','description':'Use another source-defined simultaneous assignment and finite-deck shortfall procedure; retain SEM-Q-023 for Deadly Claws slot assignment.','support':'no universal owner/tie-break is printed'}]},
        {'questionId':'SEM-Q-039','title':'Use Item declaration, payment, reveal, effect, and One Use Only discard order','decisionClass':'official-clarification-preferred','blocksRuleIds':[*GREEN_ITEM_QUESTION_BLOCKS['SEM-Q-039'],*RED_ITEM_QUESTION_BLOCKS['SEM-Q-039'],*YELLOW_ITEM_QUESTION_BLOCKS['SEM-Q-039']],'plannedRuleIds':[],'defaultProhibited':True,'sourceEvidenceRefs':['docs/rulebooks/rulebook_text.txt:lines 2889, 4882–4951','docs/rules/semantics/green-item-source-index.json','docs/rules/semantics/red-item-source-index.json','docs/rules/semantics/yellow-item-source-index.json'],'alternatives':[{'alternativeId':'SEM-Q-039-A','description':'Declare/reveal the selected Item, pay the Action-card cost, resolve its effect, then discard the One Use Only card.','support':'ordinary action presentation and effect-before-cleanup reading; exact sequence is not stated'},{'alternativeId':'SEM-Q-039-B','description':'Pay and discard the Item when it is Used, then resolve its printed effect from resolution.','support':'the trait says discarded “when Used,” which may place discard before effect completion'},{'alternativeId':'SEM-Q-039-C','description':'Use another source-defined order, including the free immediate window and discard-pile face visibility.','support':'checked sources define the transitions but not their complete relative timing/visibility'}]},
        {'questionId':'SEM-Q-040','title':'Item color-deck exhaustion, discard recycling, and multi-draw shortage','decisionClass':'official-clarification-preferred','blocksRuleIds':[*GREEN_ITEM_QUESTION_BLOCKS['SEM-Q-040'],*RED_ITEM_QUESTION_BLOCKS['SEM-Q-040'],*YELLOW_ITEM_QUESTION_BLOCKS['SEM-Q-040']],'plannedRuleIds':[],'defaultProhibited':True,'sourceEvidenceRefs':['docs/rulebooks/rulebook_text.txt:lines 2593–2600, 3530–3548, 4849–4865','docs/rules/semantics/green-item-source-index.json','docs/rules/semantics/red-item-source-index.json','docs/rules/semantics/yellow-item-source-index.json'],'alternatives':[{'alternativeId':'SEM-Q-040-A','description':'An Action/effect requiring a color-deck draw is not selectable unless every required draw is available; no discard reshuffle occurs.','support':'whole-effect legality plus no checked Item reshuffle rule'},{'alternativeId':'SEM-Q-040-B','description':'Resolve available draws and let unavailable requested cards do nothing under Component Limits.','support':'generic unavailable-component rule; assignment among multiple draws/decks remains unstated'},{'alternativeId':'SEM-Q-040-C','description':'Return or reshuffle the affected color discard pile, or apply another source-defined exhaustion procedure.','support':'TTS runtime has discard-return helpers, but runtime behavior is secondary and the official rule is absent'}]},
        {'questionId':'SEM-Q-041','title':'Selected Green face local draw and crossed-device glyph identities','decisionClass':'source-ambiguity-owner-decision-after-source-search','blocksRuleIds':GREEN_ITEM_QUESTION_BLOCKS['SEM-Q-041'],'plannedRuleIds':[],'defaultProhibited':True,'sourceEvidenceRefs':['assets/tts-mod/extract/v2-dl/tree/cards/game/greenitem-181_cards/card-00.png','assets/tts-mod/extract/v2-dl/tree/cards/game/greenitem-181_cards/card-07.png','assets/tts-mod/extract/selected-card-text-evidence.json','docs/rules/semantics/green-item-source-index.json'],'alternatives':[{'alternativeId':'SEM-Q-041-A','description':'The blank draw rectangles denote Action cards and the Stimulants crossed device denotes Not In Combat, following licensed placeholders/flags.','support':'licensed Adrenaline/Stimulants rows supply ACTION-CARD and noIntruders; secondary only'},{'alternativeId':'SEM-Q-041-B','description':'Keep every selected TTS occurrence literal and undispatched until exact source-scoped icon evidence exists.','support':'selected all-glossary comparisons record explicit no-matches'},{'alternativeId':'SEM-Q-041-C','description':'Assign another source-local card/restriction meaning established by future exact component evidence.','support':'color, position, expected logic, and nearby matched faces cannot establish identity'}]},
